// select random colors with weights from palette 

function myRandom(colors, weights) {
	let tt = 0;
	let sum = 0;

	for (let i = 0; i < colors.length; i++) {
		sum += weights[i];
	}

	let rr = random(0, sum);

	for (let j = 0; j < weights.length; j++) {

		if (weights[j] >= rr) {
			return colors[j];
		}
		rr -= weights[j];
	}

	return tt;
}

